<?php
final class ScrimController {
 public static function index():void{requireLogin();$games=ScrimModel::games();render('scrims/listar',compact('games'));}
 public static function view():void{requireLogin();$game=ScrimModel::find((int)($_GET['id']??0));if(!$game)throw new RuntimeException('Partida no encontrada.');$stats=ScrimModel::stats((int)$game['id_partida']);if(!isCoach()){$stats=array_values(array_filter($stats,fn($row)=>(int)$row['id_usuario']===(int)user()['id_usuario']));}$roles=UsuarioModel::rolesCompetitivos();render('scrims/ver',compact('game','stats','roles'));}
 public static function create():void{requireCoach();$maps=ScrimModel::maps();$players=UsuarioModel::players();$roles=UsuarioModel::rolesCompetitivos();render('scrims/crear',compact('maps','players','roles'));}
 public static function store():never{requireCoach();verifyCsrf();$date=clean('fecha',10);$map=positiveInt($_POST['id_mapa']??null);$rival=clean('equipo_rival',100);$result=clean('resultado',20);$won=positiveInt($_POST['rondas_ganadas']??null);$lost=positiveInt($_POST['rondas_perdidas']??null);
 if(!validDate($date)||!$map||!$rival||!in_array($result,['Victoria','Derrota','Empate'],true)||$won<0||$lost<0)throw new RuntimeException('Datos generales de scrim inválidos.');
 $validMaps=array_map('intval',array_column(ScrimModel::maps(),'id_mapa'));if(!in_array($map,$validMaps,true))throw new RuntimeException('Mapa no válido.');
 if(($result==='Victoria'&&$won<=$lost)||($result==='Derrota'&&$won>=$lost)||($result==='Empate'&&$won!==$lost))throw new RuntimeException('El resultado no coincide con las rondas.');
 $rows=$_POST['stats']??[];if(!is_array($rows)||count($rows)!==5)throw new RuntimeException('Deben registrarse exactamente 5 jugadores.');$stats=[];$ids=[];$allowed=[];foreach(UsuarioModel::players() as $u)$allowed[(int)$u['id_usuario']]=(int)$u['id_rol'];
 $validComp=array_map('intval',array_column(UsuarioModel::rolesCompetitivos(),'id_rol_competitivo'));
 foreach($rows as $row){if(!is_array($row))throw new RuntimeException('Estadística inválida.');$id=positiveInt($row['id_usuario']??null);$role=positiveInt($row['id_rol_jugado']??null);$comp=positiveInt($row['id_rol_competitivo']??null);$agent=trim((string)($row['agente_jugado']??''));$k=positiveInt($row['asesinatos']??null);$d=positiveInt($row['muertes']??null);$a=positiveInt($row['asistencias']??null);$acs=positiveInt($row['acs']??null);$hs=filter_var($row['porcentaje_hs']??null,FILTER_VALIDATE_FLOAT);
 if(!isset($allowed[$id])||isset($ids[$id])||!in_array($role,[2,3,4,5],true)||!in_array($comp,$validComp,true)||$agent===''||mb_strlen($agent)>50||min($k,$d,$a,$acs)<0||$hs===false||$hs<0||$hs>100)throw new RuntimeException('Revisa los 5 jugadores, sus estados, roles competitivos y estadísticas.');$ids[$id]=true;$stats[]=[$id,$role,$comp,$agent,$k,$d,$a,$acs,$hs];}
 ScrimModel::insert([$date,$map,$rival,$result,$won,$lost,clean('observaciones',2000)?:null],$stats);flash('Scrim y estadísticas guardadas.');redirect('scrims');}
 public static function updateCompetitive():never{requireCoach();verifyCsrf();$game=(int)($_POST['game']??0);$stat=positiveInt($_POST['id_stat']??null);$comp=positiveInt($_POST['id_rol_competitivo']??null);$valid=array_map('intval',array_column(UsuarioModel::rolesCompetitivos(),'id_rol_competitivo'));if(!$game||!$stat||($comp!==0&&!in_array($comp,$valid,true))||!ScrimModel::find($game))throw new RuntimeException('Datos de rol competitivo inválidos.');ScrimModel::setStatCompetitive($stat,$game,$comp?:null);flash('Rol competitivo de la scrim actualizado.');redirect('scrim-ver',['id'=>$game]);}
 public static function delete():never{requireCoach();verifyCsrf();ScrimModel::remove((int)($_POST['id']??0));flash('Scrim eliminada.');redirect('scrims');}
}
